        String[] sequences = {"",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                ""};
        String newick = "(((((sp18:0.025299055725057452,sp20:0.025299055725057452):0.3269409370336478,(sp13:0.07242089778664934,sp2:0.07242089778664934):0.2798190949720559):0.19900168166098048,sp15:0.5512416744196857):0.2518504011311369,((sp8:0.027161707109862626,sp1:0.027161707109862626):0.1806980710799901,(sp16:0.03834001780470167,sp11:0.03834001780470167):0.16951976038515107):0.5952322973609698):1.752307649623558,((sp3:0.08875190615360397,sp14:0.08875190615360397):2.298224278723977,((sp12:0.34842357564493776,sp9:0.34842357564493776):0.8473877596500768,(((sp4:0.14568142054982366,(sp10:0.13448542230383959,(sp19:0.09770853686640074,sp6:0.09770853686640074):0.036776885437438844):0.011195998245984079):0.037552162732020666,sp7:0.18323358328184433):0.700418222216517,(sp17:0.18337533964775454,sp5:0.18337533964775454):0.7002764658506068):0.3121595297966533):1.1911648495825664):0.1684235402967995):0.0;";

        String trait0Values = "sp1=0.0387876829138803988,sp2=-0.0261650640045382014,sp3=0.0000780613211212051,sp4=0.0640955976744835010,sp5=0.0631755463800323935,sp6=0.0175265726505994986,sp7=0.0285494149210851998,sp8=0.0034181730917631800,sp9=0.0381431935689817980,sp10=0.0429503413943981976,sp11=0.0322004948111379030,sp12=0.0470716865963385980,sp13=0.0547267264548012972,sp14=0.0392330272674960984,sp15=-0.0039068533176126897,sp16=0.0182309457961658990,sp17=0.0801855614646413001,sp18=0.0790165878526876003,sp19=0.0521209102564738000,sp20=0.0470196223928652998";

        int numTraits = 1;

        Alignment alignment = getAlignment(numLeaves, names, sequences);

        // Parameters
        Double[] betasArray = {0.02107573129121891};
        double meanSubst = 0.0; // 0.05; // mean substitution rate
